"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { CheckCircle, AlertCircle, Loader2 } from "lucide-react";
import Layout from "../Layout";
import { useNavigate } from "react-router-dom";

export default function CreateMeal() {
  const navigate = useNavigate();

  // Define the days for one week (Monday to Sunday)
  const daysOfWeek = ["lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche"];

  // Map daysOfWeek to formData keys (in French)
  const dayKeys = ["lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche"];

  // Calculate the next Monday as the default start date
  const getNextMonday = () => {
    const today = new Date();
    const day = today.getDay(); // 0 = Sunday, 1 = Monday, ..., 6 = Saturday
    const daysUntilMonday = day === 0 ? 1 : day === 1 ? 7 : 8 - day;
    const nextMonday = new Date(today);
    nextMonday.setDate(today.getDate() + daysUntilMonday);
    return nextMonday.toISOString().split("T")[0];
  };

  const [formData, setFormData] = useState({
    lundi: {
      breakfast: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
      lunch: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
      dinner: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
    },
    mardi: {
      breakfast: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
      lunch: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
      dinner: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
    },
    mercredi: {
      breakfast: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
      lunch: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
      dinner: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
    },
    jeudi: {
      breakfast: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
      lunch: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
      dinner: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
    },
    vendredi: {
      breakfast: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
      lunch: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
      dinner: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
    },
    samedi: {
      breakfast: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
      lunch: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
      dinner: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
    },
    dimanche: {
      breakfast: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
      lunch: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
      dinner: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
    },
  });

  const [mealSuggestions, setMealSuggestions] = useState({});
  const [startDate, setStartDate] = useState(getNextMonday);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    fetchMeals();
  }, []);

  const fetchMeals = async () => {
    try {
      const token = localStorage.getItem("token");
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/meals`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const uniqueMeals = {};
      response.data.forEach((meal) => {
        if (!uniqueMeals[meal.type] || !uniqueMeals[meal.type].some((m) => m.mealName === meal.mealName)) {
          uniqueMeals[meal.type] = uniqueMeals[meal.type] || [];
          uniqueMeals[meal.type].push({ mealName: meal.mealName, priceOfMeal: meal.priceOfMeal });
        }
      });
      setMealSuggestions(uniqueMeals);
    } catch (error) {
      setError("Erreur lors de la récupération des repas existants.");
    }
  };

  const handleSelectChange = (e, dayKey, mealType) => {
    const value = e.target.value;
    if (value === "Create New") {
      setFormData((prev) => ({
        ...prev,
        [dayKey]: {
          ...prev[dayKey],
          [mealType]: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "text" },
        },
      }));
    } else {
      const matchingMeal = (mealSuggestions[mealType === "breakfast" ? "Breakfast" : mealType === "lunch" ? "Lunch" : "Dinner"] || []).find(
        (meal) => meal.mealName === value
      );
      if (matchingMeal) {
        setFormData((prev) => ({
          ...prev,
          [dayKey]: {
            ...prev[dayKey],
            [mealType]: { mealName: matchingMeal.mealName, priceOfMeal: matchingMeal.priceOfMeal.toString(), isSelected: true, inputType: "select" },
          },
        }));
      }
    }
  };

  const handleTextChange = (e, dayKey, mealType) => {
    const value = e.target.value;
    setFormData((prev) => ({
      ...prev,
      [dayKey]: {
        ...prev[dayKey],
        [mealType]: { ...prev[dayKey][mealType], mealName: value, isSelected: false },
      },
    }));
  };

  const handlePriceChange = (e, dayKey, mealType) => {
    const value = e.target.value;
    setFormData((prev) => ({
      ...prev,
      [dayKey]: {
        ...prev[dayKey],
        [mealType]: { ...prev[dayKey][mealType], priceOfMeal: value, isSelected: false },
      },
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess("");
    setIsSubmitting(true);

    const token = localStorage.getItem("token");
    const mealData = [];

    const start = new Date(startDate);
    daysOfWeek.forEach((day, index) => {
      const date = new Date(start);
      date.setDate(start.getDate() + index);
      date.setHours(0, 0, 0, 0);

      ["breakfast", "lunch", "dinner"].forEach((mealType) => {
        const meal = formData[dayKeys[index]][mealType];
        if (meal.mealName && meal.priceOfMeal) {
          mealData.push({
            mealName: meal.mealName,
            type: mealType === "breakfast" ? "Breakfast" : mealType === "lunch" ? "Lunch" : "Dinner",
            date,
            priceOfMeal: Number(meal.priceOfMeal),
          });
        }
      });
    });

    try {
      for (const meal of mealData) {
        if (!meal.mealName || !meal.priceOfMeal) {
          throw new Error("Tous les champs sont requis pour chaque repas.");
        }
        await axios.post(`${process.env.REACT_APP_API_URL}/api/meals`, meal, {
          headers: { Authorization: `Bearer ${token}` },
        });
      }
      setSuccess("Repas pour la semaine créés avec succès !");
      setTimeout(() => navigate("/MealsForNextDayC"), 2000);
      setFormData({
        lundi: {
          breakfast: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
          lunch: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
          dinner: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
        },
        mardi: {
          breakfast: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
          lunch: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
          dinner: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
        },
        mercredi: {
          breakfast: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
          lunch: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
          dinner: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
        },
        jeudi: {
          breakfast: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
          lunch: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
          dinner: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
        },
        vendredi: {
          breakfast: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
          lunch: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
          dinner: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
        },
        samedi: {
          breakfast: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
          lunch: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
          dinner: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
        },
        dimanche: {
          breakfast: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
          lunch: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
          dinner: { mealName: "", priceOfMeal: "", isSelected: false, inputType: "select" },
        },
      });
    } catch (err) {
      setError(err.message || "Erreur lors de la création des repas.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Layout>
      <div className="max-w-5xl mx-auto">
        <div className="bg-white rounded-xl shadow-xl overflow-hidden">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <h2 className="text-2xl font-bold tracking-tight">Créer les repas de la semaine</h2>
            <div className="mt-4">
              <label htmlFor="startDate" className="block text-sm font-medium text-white">
                Date de départ (Prochain Lundi)
              </label>
              <input
                type="date"
                id="startDate"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                className="mt-1 px-4 py-2 border border-gray-300 rounded-md focus:ring-[#00717F] focus:border-[#00717F] text-black"
                required
              />
            </div>
            <p className="text-white/80 mt-1">Planifiez les repas pour 7 jours (Lundi à Dimanche)</p>
          </div>

          {(error || success) && (
            <div
              className={`p-4 ${error ? "bg-red-50" : "bg-green-50"} border-l-4 ${
                error ? "border-red-500" : "border-green-500"
              } flex items-center gap-3`}
            >
              {error ? (
                <AlertCircle className="h-5 w-5 text-red-500" />
              ) : (
                <CheckCircle className="h-5 w-5 text-green-500" />
              )}
              <p className={`text-sm ${error ? "text-red-700" : "text-green-700"}`}>
                {error || success}
              </p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            {daysOfWeek.map((day, index) => (
              <div key={day} className="space-y-4 border-b pb-4">
                <h3 className="text-xl font-medium text-gray-900 capitalize">{day}</h3>
                {["breakfast", "lunch", "dinner"].map((mealType) => (
                  <div key={mealType} className="space-y-2">
                    <h4 className="text-lg font-medium text-gray-700 capitalize">
                      {mealType === "breakfast" ? "Petit-déjeuner" : mealType === "lunch" ? "Déjeuner" : "Dîner"}
                    </h4>
                    <div className="space-y-2">
                      {formData[dayKeys[index]][mealType].inputType === "select" ? (
                        <>
                          <label
                            htmlFor={`${day}-${mealType}-select`}
                            className="block mb-2 text-sm font-medium text-gray-900 dark:text-white"
                          >
                            Sélectionner un repas
                          </label>
                          <select
                            id={`${day}-${mealType}-select`}
                            value={formData[dayKeys[index]][mealType].mealName}
                            onChange={(e) => handleSelectChange(e, dayKeys[index], mealType)}
                            className="bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 block w-full p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500"
                          >
                            <option value="">Choisir un repas</option>
                            {(mealSuggestions[mealType === "breakfast" ? "Breakfast" : mealType === "lunch" ? "Lunch" : "Dinner"] || []).map(
                              (meal, index) => (
                                <option key={index} value={meal.mealName}>
                                  {meal.mealName}
                                </option>
                              )
                            )}
                            <option value="Create New">Créer un nouveau</option>
                          </select>
                        </>
                      ) : (
                        <div className="relative">
                          <input
                            type="text"
                            name="mealName"
                            value={formData[dayKeys[index]][mealType].mealName}
                            onChange={(e) => handleTextChange(e, dayKeys[index], mealType)}
                            placeholder="Entrer un nouveau repas..."
                            className="w-full px-4 py-3 border border-gray-300 rounded-md focus:ring-[#00717F] focus:border-[#00717F]"
                            required
                          />
                        </div>
                      )}
                      <input
                        type="number"
                        name="priceOfMeal"
                        value={formData[dayKeys[index]][mealType].priceOfMeal}
                        onChange={(e) => handlePriceChange(e, dayKeys[index], mealType)}
                        placeholder="Entrer le prix (DH)"
                        className="w-full px-4 py-3 border border-gray-300 rounded-md focus:ring-[#00717F] focus:border-[#00717F]"
                        required
                        min="0"
                        step="0.01"
                        disabled={formData[dayKeys[index]][mealType].isSelected}
                      />
                    </div>
                  </div>
                ))}
              </div>
            ))}
            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white py-3 rounded-md hover:bg-gradient-to-r from-[#00717F] to-[#C8A45D]/90 flex justify-center items-center"
            >
              {isSubmitting ? (
                <Loader2 className="animate-spin h-5 w-5 mr-2" />
              ) : null}
              {isSubmitting ? "Création en cours..." : "Créer les repas pour 7 jours"}
            </button>
          </form>
        </div>
      </div>
    </Layout>
  );
}
